 "content": "from collections import deque


def transform(grid):
    """Keep substantial colored rectangular objects and restore their interiors."""
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = [[False] * w for _ in range(h)]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            # Isolated marks are clutter. The real objects are sizeable solid
            # rectangles, occasionally punctured by single-cell distractors.
            if len(cells) < 4:
                continue
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            if (r1 - r0 + 1) * (c1 - c0 + 1) <= len(cells) + 4:
                for y in range(r0, r1 + 1):
                    for x in range(c0, c1 + 1):
                        out[y][x] = color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
